use super::*;

// ============================================================
// MS-XCA (Xpress / Xpress Huffman / LZNT1) tests
// ============================================================
//
// The known-answer vectors below originate from [MS-XCA] section 3
// ("Examples") and from test streams generated by the Windows
// RtlCompressBuffer encoder (mirrored in Samba's lib/compression
// test suite). They exercise decode conformance against byte-exact
// streams produced by the reference implementation.

#[test]
fn xpress_spec_example_literals() {
    // [MS-XCA] 3.1 example 1: all-literal stream.
    let mut input = vec![0x3f, 0x00, 0x00, 0x00];
    input.extend_from_slice(b"abcdefghijklmnopqrstuvwxyz");
    let dec = xca::lz77::decode(&input).unwrap();
    assert_eq!(dec, b"abcdefghijklmnopqrstuvwxyz");
}

#[test]
fn xpress_spec_example_match() {
    // [MS-XCA] 3.1 example 2: "abc" + match (distance 3, length 297).
    let input = [
        0xff, 0xff, 0xff, 0x1f, 0x61, 0x62, 0x63, 0x17, 0x00, 0x0f, 0xff, 0x26, 0x01,
    ];
    let expected: Vec<u8> = b"abc".iter().cycle().take(300).copied().collect();
    let dec = xca::lz77::decode(&input).unwrap();
    assert_eq!(dec, expected);
}

#[test]
fn xpress_windows_vector_mixed() {
    // Windows encoder output (via Samba test_lzxpress): literals,
    // two matches, trailing match-flag padding.
    let input = [
        0xff, 0x21, 0x00, 0x04, 0x74, 0x68, 0x69, 0x73, 0x20, 0x10, 0x00, 0x61, 0x20, 0x74, 0x65,
        0x73, 0x74, 0x2E, 0x20, 0x61, 0x6E, 0x64, 0x20, 0x9F, 0x00, 0x04, 0x20, 0x74, 0x6F, 0x6F,
    ];
    let dec = xca::lz77::decode(&input).unwrap();
    assert_eq!(dec, b"this is a test. and this is a test too");
}

#[test]
fn xpress_windows_vector_shared_nibble() {
    // Two long matches sharing one extended-length nibble byte.
    let input = [
        0xff, 0xff, 0xff, 0x5f, 0x61, 0x07, 0x00, 0x21, 0x62, 0x67, 0x00,
    ];
    let dec = xca::lz77::decode(&input).unwrap();
    assert_eq!(dec, b"aaaaaaaaaaaabaaaaaaaaaaaa");
}

#[test]
fn xpress_windows_vector_flag_overflow() {
    // 31 literals + minimum match + trailing literal: the second flag
    // word slot position is exercised.
    let input = [
        0x01, 0x00, 0x00, 0x00, 0x61, 0x62, 0x63, 0x64, 0x65, 0x66, 0x67, 0x68, 0x69, 0x6a, 0x6b,
        0x6c, 0x6d, 0x6e, 0x6f, 0x70, 0x71, 0x72, 0x73, 0x74, 0x75, 0x76, 0x77, 0x78, 0x79, 0x7a,
        0x30, 0x31, 0x32, 0x33, 0x34, 0xf0, 0x00, 0xff, 0xff, 0xff, 0x7f, 0x61,
    ];
    let dec = xca::lz77::decode(&input).unwrap();
    assert_eq!(dec, b"abcdefghijklmnopqrstuvwxyz01234abca");
}

#[test]
fn xpress_windows_vector_empty_tail_flags() {
    // 31 literals + minimum match; final flag word is all padding.
    let input = [
        0x01, 0x00, 0x00, 0x00, 0x61, 0x62, 0x63, 0x64, 0x65, 0x66, 0x67, 0x68, 0x69, 0x6a, 0x6b,
        0x6c, 0x6d, 0x6e, 0x6f, 0x70, 0x71, 0x72, 0x73, 0x74, 0x75, 0x76, 0x77, 0x78, 0x79, 0x7a,
        0x30, 0x31, 0x32, 0x33, 0x34, 0xf0, 0x00, 0xff, 0xff, 0xff, 0xff,
    ];
    let dec = xca::lz77::decode(&input).unwrap();
    assert_eq!(dec, b"abcdefghijklmnopqrstuvwxyz01234abc");
}

