#[test]
fn lznt1_stored_chunk() {
    // Stored (uncompressed) chunk: header 0x3000 | (size-3), raw body,
    // end-of-buffer marker.
    let mut input = vec![0x02, 0x30]; // header: sig=3, size-3=2 -> 5 bytes total
    input.extend_from_slice(b"abc");
    input.extend_from_slice(&[0, 0]);
    let dec = xca::lznt1::decode(&input).unwrap();
    assert_eq!(dec, b"abc");
}

#[test]
fn lznt1_compressed_chunk_literals() {
    // Compressed chunk: one flag group, all-literal flags.
    let mut input = vec![0x08, 0xb0]; // header: 0x8000|0x3000|(11-3) -> 11 bytes
    input.push(0x00); // flag byte: 8 literals
    input.extend_from_slice(b"ABCDEFGH");
    input.extend_from_slice(&[0, 0]);
    let dec = xca::lznt1::decode(&input).unwrap();
    assert_eq!(dec, b"ABCDEFGH");
}

#[test]
fn lznt1_compressed_chunk_match() {
    // Compressed chunk: 'a','b','c' literals + match (displacement 3,
    // length 6). At position u=3, M=4 displacement bits, L=12 length
    // bits: word = ((3-1)<<12) | (6-3) = 0x2003.
    let mut input = vec![0x05, 0xb0]; // header: 0x8000|0x3000|(8-3) -> 8 bytes
    input.push(0x08); // flag byte: elements 0-2 literals, element 3 match
    input.extend_from_slice(b"abc");
    input.extend_from_slice(&0x2003u16.to_le_bytes());
    input.extend_from_slice(&[0, 0]);
    let dec = xca::lznt1::decode(&input).unwrap();
    assert_eq!(dec, b"abcabcabc");
}

#[test]
fn xca_roundtrips() {
    let cases: &[&[u8]] = &[
        b"",
        b"a",
        b"hello world hello world hello world",
        b"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
    ];
    let mut big = Vec::new();
    for _ in 0..1000 {
        big.extend_from_slice(b"the quick brown fox jumps over the lazy dog. ");
    }
    for data in cases
        .iter()
        .copied()
        .chain(core::iter::once(big.as_slice()))
    {
        assert_eq!(xca::lz77::decode(&xca::lz77::encode(data)).unwrap(), data);
        assert_eq!(
            xca::huffman::decode(&xca::huffman::encode(data)).unwrap(),
            data
        );
        assert_eq!(xca::lznt1::decode(&xca::lznt1::encode(data)).unwrap(), data);
    }
}
